        if (executedInputs.length === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-good', name: 'lookup', input: {q: 'real query'}}};
          yield STOP_FOR_TOOL;
          return;
        }
        yield {type: 'text', text: 'the weather is sunny'};
        yield STOP_DONE;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

